        MonoidStmtType::Have => {
            assert!(param.inout_type == InoutType::BorrowIn);
            Expr::Verbatim(quote! { #name.value() })
        }
        MonoidStmtType::Remove => {
            assert!(param.inout_type == InoutType::In);
            Expr::Verbatim(quote! { #name.value() })
        }
